/* ── Screen destroy ──────────────────────────────────────────────── */

void ui_sd_card_files_screen_destroy(void)
{
    if (ui_sd_card_files) lv_obj_del(ui_sd_card_files);
    /* lv_obj_del fires LV_EVENT_DELETE on all descendants → frees sd_item_t */

    ui_sd_card_files    = NULL;
    ui_sd_card_files_bg = NULL;
    ui_down             = NULL;
    ui_sd_header_bg     = NULL;
    ui_list_border      = NULL;
    ui_key_prompts_bg   = NULL;
    ui_key_a_bg         = NULL;
    ui_key_b_bg         = NULL;
    ui_sd_header_label  = NULL;
    ui_key_a_enter      = NULL;
    ui_key_b_back       = NULL;
    _file_list          = NULL;
    strcpy(_current_path, "/");
}
